ALTER TABLE invitation_phones ADD COLUMN last_revision INTEGER NOT NULL DEFAULT 0 CHECK(last_revision>=0);ALTER TABLE invitation_consents ADD COLUMN transport_phone_generation INTEGER NOT NULL DEFAULT 0 CHECK(transport_phone_generation>=0);ALTER TABLE invitation_events ADD COLUMN revision INTEGER NOT NULL DEFAULT 0 CHECK(revision>=0);UPDATE invitation_events SET revision=rowid;UPDATE invitation_phones SET last_revision=coalesce((SELECT max(revision) FROM invitation_events WHERE phone_id=invitation_phones.id),0);CREATE UNIQUE INDEX invitation_events_revision ON invitation_events(phone_id,revision);DROP TABLE invitation_schema;CREATE TABLE invitation_schema (singleton INTEGER PRIMARY KEY CHECK(singleton=1), version INTEGER NOT NULL CHECK(version=2)) STRICT;INSERT INTO invitation_schema VALUES(1,2);